                                     gC);
    else {
        if ((cols % 32) == 0)
            Klas_SPMM_g_spmm_f32_32x32x8(rows, shared, cols, gA, row_indices,
                                         gB, gC);
        else {
            if ((cols % 16) == 0)
                Klas_SPMM_g_spmm_f32_32x16x4(rows, shared, cols, gA,
                                             row_indices, gB, gC);
