                if ((cols % 8) == 0)
                    Klas_SPMM_g_spmm_f32_32x8x2(rows, shared, cols, gA,
                                                row_indices, gB, gC);
                else
                    Klas_SPMM_g_spmm_f32_32x4x1(rows, shared, cols, gA,
                                                row_indices, gB, gC);
            }
        }
    }
